import{_ as a,o,c as i,a3 as t}from"./chunks/framework.BZCmpA0A.js";const u=JSON.parse('{"title":"Spec 24：WUWAOS 功能示範影片","description":"","frontmatter":{},"headers":[],"relativePath":"SPEC-24-demo-video.md","filePath":"SPEC-24-demo-video.md","lastUpdated":1793260797000}'),r={name:"SPEC-24-demo-video.md"};function l(s,e,n,d,p,c){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="spec-24-wuwaos-功能示範影片" tabindex="-1">Spec 24：WUWAOS 功能示範影片 <a class="header-anchor" href="#spec-24-wuwaos-功能示範影片" aria-label="Permalink to &quot;Spec 24：WUWAOS 功能示範影片&quot;">​</a></h1><h2 id="目標與範圍" tabindex="-1">目標與範圍 <a class="header-anchor" href="#目標與範圍" aria-label="Permalink to &quot;目標與範圍&quot;">​</a></h2><p>在真實執行中的 QEMU 操作目前可示範的主要功能，錄成影片並放在 GitHub repository。影片使用獨立 WUFS 與 swap 磁碟，保留既有使用者磁碟；不修改作業系統程式、不加入測試程式碼。</p><h2 id="錄製方式" tabindex="-1">錄製方式 <a class="header-anchor" href="#錄製方式" aria-label="Permalink to &quot;錄製方式&quot;">​</a></h2><p>使用 WSL Ubuntu 執行 QEMU virt、單核心與 128 MiB RAM；透過標準輸入送出命令，擷取真實序列埠輸出並渲染終端畫面，再以 FFmpeg 編碼 MP4。外框與章節標題是後製顯示；內容是當次 QEMU 輸出，並非 Windows 桌面錄影。影片無旁白。獨立的示範磁碟及暫存錄製工具放在 Git 忽略的 build 目錄，不納入提交。</p><h2 id="示範內容" tabindex="-1">示範內容 <a class="header-anchor" href="#示範內容" aria-label="Permalink to &quot;示範內容&quot;">​</a></h2><ol><li>開機動畫、shell、help 和清畫面。</li><li>spawn worker、ps、PCB 檢視、wakeup 與 wait 回收。</li><li>run counter 的 fork／exec、等待、喚醒與回收；counter 會主動 yield，這段不能單獨證明計時器搶占。</li><li>demo sync 顯示 Mutex 與 Semaphore 等待、喚醒和回收。</li><li>writer | reader 的管道與回收。</li><li>切換目錄、建立／寫入／讀取／複製檔案，刪除檔案與確認後刪除資料夾。</li><li>fan 編輯、儲存與 cat 讀回。</li><li>workstate 顯示 CPU 和記憶體資料，按 q 返回 shell。</li><li>降低 VM 常駐頁預算、配置／寫入頁面、查看缺頁與 swap 計數、讀回頁面，再清理並恢復預算。</li><li>行程狀態、help 及退出 QEMU。</li></ol><h2 id="驗證與限制" tabindex="-1">驗證與限制 <a class="header-anchor" href="#驗證與限制" aria-label="Permalink to &quot;驗證與限制&quot;">​</a></h2><p>實際 QEMU 終端紀錄確認 worker 和 counter 收集、sync demo 完成、pipe 傳輸、檔案寫入與 fan 讀回；VM 統計顯示 swap_in=7、swap_out=14，頁 0 的三處資料均讀回 65。抽查影片中編輯器、退出後畫面、workstate 及 VM 畫面；影片為約 2 分鐘、1280×720、H.264 MP4、6 fps。各功能的其他邊界並未由此影片完整驗證，顯示畫面只是一次示範。錄製未使用或修改原本的 build/wuwaos.img。</p><p>影片：<a href="https://github.com/johnson931128/WUWAOS/blob/main/docs/media/wuwaos-demo.mp4" target="_blank" rel="noreferrer">WUWAOS QEMU demo on GitHub</a>。</p>',10)])])}const m=a(r,[["render",l]]);export{u as __pageData,m as default};
